//! 8x16 bitmap font: GNU Unifont, U+0020..U+00FF (ASCII + Latin-1). See `font_data.rs`
//! (generated by `scripts/gen_font.py`) and `assets/fonts/UNIFONT-LICENSE.txt`.

#![allow(dead_code)] // Text API for later users; not all of it is used yet.

use crate::font_data::{FIRST_CHAR, GLYPHS, LAST_CHAR, REPLACEMENT};
use crate::gfx::{Color, DrawTarget};

pub const GLYPH_W: usize = 8;
pub const GLYPH_H: usize = 16;

/// The 16 row bytes of a glyph (MSB = leftmost pixel). Unsupported characters give a replacement box.
pub fn glyph(c: char) -> &'static [u8; 16] {
    let cp = c as u32;
    if (FIRST_CHAR..=LAST_CHAR).contains(&cp) {
        &GLYPHS[(cp - FIRST_CHAR) as usize]
    } else {
        &REPLACEMENT
    }
}

/// Draw one glyph with its top-left at (x, y), each font pixel becoming a `scale` x `scale` block.
/// `bg` of `None` leaves the background untouched.
pub fn draw_glyph(
    t: &mut dyn DrawTarget,
    x: i32,
    y: i32,
    c: char,
    fg: Color,
    bg: Option<Color>,
    scale: i32,
) {
    let g = glyph(c);
    // Fast path for the console: opaque, unscaled, fully on target.
    if let (1, Some(bg)) = (scale, bg)
        && x >= 0
        && y >= 0
        && x as usize + GLYPH_W <= t.width()
        && y as usize + GLYPH_H <= t.height()
    {
        let stride = t.stride();
        let px = t.pixels_mut();
        for (row, &bits) in g.iter().enumerate() {
            let base = (y as usize + row) * stride + x as usize;
            for (col, p) in px[base..base + GLYPH_W].iter_mut().enumerate() {
                *p = if bits & (0x80 >> col) != 0 { fg } else { bg };
            }
        }
        return;
    }
    if let Some(bg) = bg {
        t.fill_rect(x, y, GLYPH_W as i32 * scale, GLYPH_H as i32 * scale, bg);
    }
    draw_glyph_alpha(t, x, y, c, fg, 255, scale);
}

/// Draw one glyph's set pixels blended over whatever is already on the target (`alpha` 0..=255),
/// so text works over any background: gradients, images, translucent panels.
pub fn draw_glyph_alpha(
    t: &mut dyn DrawTarget,
    x: i32,
    y: i32,
    c: char,
    fg: Color,
    alpha: u8,
    scale: i32,
) {
    let g = glyph(c);
    for (row, &bits) in g.iter().enumerate() {
        let mut col = 0;
        while col < GLYPH_W {
            if bits & (0x80 >> col) == 0 {
                col += 1;
                continue;
            }
            // Merge a run of set pixels into one rectangle.
            let start = col;
            while col < GLYPH_W && bits & (0x80 >> col) != 0 {
                col += 1;
            }
            t.fill_rect_alpha(
                x + start as i32 * scale,
                y + row as i32 * scale,
                (col - start) as i32 * scale,
                scale,
                fg,
                alpha,
            );
        }
    }
}

/// Draw a string left to right. Returns the x just past the last glyph.
pub fn draw_str(
    t: &mut dyn DrawTarget,
    x: i32,
    y: i32,
    s: &str,
    fg: Color,
    bg: Option<Color>,
    scale: i32,
) -> i32 {
    let mut x = x;
    for c in s.chars() {
        draw_glyph(t, x, y, c, fg, bg, scale);
        x += GLYPH_W as i32 * scale;
    }
    x
}

/// Like [`draw_str`] but each glyph is alpha blended over what is there. Returns the end x.
pub fn draw_str_alpha(
    t: &mut dyn DrawTarget,
    x: i32,
    y: i32,
    s: &str,
    fg: Color,
    alpha: u8,
    scale: i32,
) -> i32 {
    let mut x = x;
    for c in s.chars() {
        draw_glyph_alpha(t, x, y, c, fg, alpha, scale);
        x += GLYPH_W as i32 * scale;
    }
    x
}

/// Width in pixels of `s` at `scale`.
pub fn str_width(s: &str, scale: i32) -> i32 {
    s.chars().count() as i32 * GLYPH_W as i32 * scale
}
